/** Explicit isolated fixture authority, never packaged or registered by the release mod. */
final class DChestCourierScene {
 final DComeScene arena;final ServerLevel level;final Path evidence;final String caseId;final BlockPos sourcePos,destPos;final UUID world;final StorageMetadataStore store;final StorageRegistry registry;final StorageIncarnationAdapter identities;final MinecraftStorageAdapter reader;final StorageAccessPolicy.Scope scope;
 Binding source,destination;final java.util.concurrent.atomic.AtomicReference<Binding> attested;final MinecraftTransferAdapter transfer;final MinecraftNavigationAdapter navigation;MinecraftNavigationAdapter.Route route;DeliveryPolicy.Session session;MinecraftTransferAdapter.Batch batch;
 String campaign="";boolean exclusive=true,control=true;long custodyRevision=0,deadline;int sequence=0;Item currentItem=Items.OAK_PLANKS;long transferNs;boolean ready=false;TransferObservation last;
 private DChestCourierScene(ServerLevel level,BlockPos origin,ServerPlayer principal,Path evidence,String caseId,StorageMetadataStore store,DChestCourierScene previous){
  this.level=level;this.evidence=evidence;this.caseId=caseId;this.store=store;world=DTestAuthority.acquireTaggedWorld().world();arena=new DComeScene(level,origin,principal,evidence,caseId,actorId(caseId,origin),UUID.nameUUIDFromBytes((caseId+origin+"citizen").getBytes(java.nio.charset.StandardCharsets.UTF_8)));sourcePos=origin.offset(2,0,7);destPos=origin.offset(17,0,7);level.setBlockAndUpdate(sourcePos,Blocks.CHEST.defaultBlockState());level.setBlockAndUpdate(destPos,Blocks.CHEST.defaultBlockState());
  attested=previous==null?new java.util.concurrent.atomic.AtomicReference<>():previous.attested;
  if(previous==null){var caller=new Caller(world,DNativeScene.PRINCIPAL);registry=new StorageRegistry(store,new StorageRegistry.Authority(){public boolean controls(Caller c,Owner o){return c.equals(caller) && Objects.equals(o.id(),DNativeScene.PRINCIPAL);}public boolean mayGrant(Caller c,StorageRegistry.Record r,Grant g){return c.equals(caller);}public boolean allows(Caller c,Action a,StorageRegistry.Record r){return c.equals(caller) && (a!=Action.COMMIT_BIND || attested.get()!=null && attested.get().storage().equals(r.id()));}});
   identities=new StorageIncarnationAdapter(level,world,(a,w,id,pos)->world.equals(w));identities.updateMetadata(store.snapshot());var policy=DStorageAdaptersGameTests.policy(level,registry,identities,()->true);reader=new MinecraftStorageAdapter(level,identities,registry::snapshot,policy,(sc,id,op,pos)->true);
  }else{registry=previous.registry;identities=previous.identities;reader=previous.reader;}
  scope=new StorageAccessPolicy.Scope(world,UUID.fromString("d0800000-0000-4000-8000-000000000002"),principal.getUUID(),arena.identity.citizen());
  transfer=new MinecraftTransferAdapter(level,arena.actor,arena.identity,scope,reader,(key,order)->{if(!order.equals(order.stream().sorted().toList()) || order.size()!=3)throw new IllegalStateException("canonical participant resource order");return new MinecraftTransferAdapter.Control(arena.identity,control,exclusive,custodyRevision);});deadline=level.getGameTime()+5000;
  navigation=new MinecraftNavigationAdapter(level,arena.actor,(key,tick)->new MinecraftNavigationAdapter.Control(arena.identity,control,Limits.maximum(),deadline));
 }
 static UUID actorId(String id,BlockPos origin){return UUID.nameUUIDFromBytes((id+origin+"actor").getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 static void open(ServerLevel level,BlockPos origin,ServerPlayer p,Path evidence,String caseId,Consumer<DChestCourierScene> next){open(level,origin,p,evidence,caseId,null,next);}
 static void open(ServerLevel level,BlockPos origin,ServerPlayer p,Path evidence,String caseId,DChestCourierScene previous,Consumer<DChestCourierScene> next){open(level,origin,p,evidence,caseId,previous,Integer.toString(origin.getX()),next);}
 static void open(ServerLevel level,BlockPos origin,ServerPlayer p,Path evidence,String caseId,DChestCourierScene previous,String labelSuffix,Consumer<DChestCourierScene> next){Consumer<StorageMetadataStore> ready=store->{var s=new DChestCourierScene(level,origin,p,evidence,caseId,store,previous);s.add(s.sourcePos,"source-"+labelSuffix,Permission.WITHDRAW,b->{s.source=b;s.add(s.destPos,"destination-"+labelSuffix,Permission.DEPOSIT,d->{s.destination=d;s.ready=true;next.accept(s);});});};if(previous==null)when(level,StorageMetadataStore.createNew(evidence.resolve("metadata"),DTestAuthority.acquireTaggedWorld().world()),ready);else{if(previous.level!=level)throw new IllegalArgumentException("same isolated native level");ready.accept(previous.store);}}
 static void openExisting(ServerLevel level,BlockPos origin,ServerPlayer p,Path evidence,String caseId,Path metadata,Consumer<DChestCourierScene> next){when(level,StorageMetadataStore.open(metadata,DTestAuthority.acquireTaggedWorld().world()),store->{var s=new DChestCourierScene(level,origin,p,evidence,caseId,store,null);s.add(s.sourcePos,caseId+"-source",Permission.WITHDRAW,b->{s.source=b;s.add(s.destPos,caseId+"-destination",Permission.DEPOSIT,d->{s.destination=d;s.ready=true;next.accept(s);});});});}
 static <T> void when(ServerLevel level,CompletionStage<T> future,Consumer<T> next){future.whenComplete((value,error)->level.getServer().execute(()->{if(error!=null)throw new CompletionException(error);next.accept(value);}));}
 void add(BlockPos pos,String label,Permission operation,Consumer<Binding> next){var c=new Caller(world,DNativeScene.PRINCIPAL);when(level,registry.registerMetadata(c,registry.snapshot().revision(),new Owner(OwnerKind.PLAYER,DNativeScene.PRINCIPAL),label,StorageBindingRules.SINGLE,Set.of(),List.of(new Grant(new Owner(OwnerKind.PUBLIC,null),Set.of(operation)))),a->{ack(a);identities.updateMetadata(registry.snapshot());var plan=identities.plan(a.storage(),1,pos);var snapshot=registry.snapshot();when(level,registry.prepareBinding(c,snapshot.revision(),a.storage(),snapshot.records().get(a.storage()).revision(),plan.intent().wire()),b->{ack(b);identities.updateMetadata(registry.snapshot());attested.set(identities.write(plan));var prepared=registry.snapshot();when(level,registry.acknowledgeBinding(c,prepared.revision(),a.storage(),prepared.records().get(a.storage()).revision(),attested.get().wire()),d->{ack(d);identities.updateMetadata(registry.snapshot());next.accept(identities.resolve(a.storage()).orElseThrow());});});});}
 static void ack(StorageMetadataStore.Ack a){if(a.status()!=StorageMetadataStore.Status.ACKNOWLEDGED)throw new IllegalStateException("fixture metadata ack "+a);}
 Container source(){return(Container)level.getBlockEntity(sourcePos);}Container destination(){return(Container)level.getBlockEntity(destPos);}
 DeliveryPolicy.Endpoint endpoint(Binding b){var members=new HashSet<UUID>();for(var m:b.topology().members())members.add(m.incarnation());return new DeliveryPolicy.Endpoint(world,b.storage(),b.topology().dimension(),members);}
 void reset(String name,Item item,int quantity,int sourceCount,int old,int destCount){reset(name,item,quantity,sourceCount,old,destCount,true,false);}
 void reset(String name,Item item,int quantity,int sourceCount,int old,int destCount,boolean explicit,boolean selected){
  if(route!=null && !route.observation().terminal())route.cancel();if(!arena.actor.getNavigation().isDone())arena.actor.getNavigation().stop();campaign=name;currentItem=item;deadline=level.getGameTime()+5000;fill(source(),item,sourceCount);fill(destination(),item,destCount);fill(arena.actor.getInventory(),item,old);source().setChanged();destination().setChanged();arena.actor.getInventory().setChanged();custodyRevision++;
  var goal=new DeliveryPolicy.Goal(UUID.nameUUIDFromBytes((caseId+"-"+(++sequence)).getBytes(java.nio.charset.StandardCharsets.UTF_8)),arena.identity.citizen(),endpoint(source),endpoint(destination),reader.describeItem(new ItemStack(item)),quantity,explicit,selected);session=new DeliveryPolicy.Session(goal);batch=null;last=null;route=null;frame("BEFORE",null);
 }
 TransferObservation withdraw(){long ns=System.nanoTime();var w=transfer.withdraw(session,source,destination,new ItemStack(currentItem),null);transferNs=System.nanoTime()-ns;batch=w.batch();last=w.observation();session.observe(last);frame("WITHDRAW",last);return last;}
 void travel(){travelTo(true);}
 void home(){travelTo(false);}
 void travelTo(boolean toDestination){var resolved=travelQuery(toDestination).step();if(resolved.status()!=StorageResolution.Status.RESOLVED)throw new IllegalStateException("native destination resolution "+resolved.status());acceptTravel(resolved,toDestination);}
 void acceptTravel(StorageResolution resolved,boolean toDestination){route=navigation.storage(arena.identity,scope,resolved.endpoint(),toDestination?Permission.DEPOSIT:Permission.WITHDRAW,reader);frame("TRAVEL_ACCEPTED",null);}
 StorageResolver.Query travelQuery(boolean toDestination){Binding target=toDestination?destination:source;Permission operation=toDestination?Permission.DEPOSIT:Permission.WITHDRAW;var m=target.topology().members().getFirst();var point=new Point(arena.identity.dimension(),m.x()-.5,m.y(),m.z()+.5);
  // Use the public authorized bound-storage route. The D04 resolver retains one opaque endpoint.
  var policy=DStorageAdaptersGameTests.policy(level,registry,identities,()->true);var resolver=new StorageResolver(registry::snapshot,policy,new StorageResolver.NativePort(){
   public StorageResolver.View view(StorageAccessPolicy.Scope sc,long tick){var p=new StorageResolver.Position(arena.identity.dimension(),Math.round(arena.actor.getX()*1000),Math.round(arena.actor.getY()*1000),Math.round(arena.actor.getZ()*1000));return new StorageResolver.View(sc,target.epoch(),1,tick,p,p,true);}
   public StorageResolver.Observation observe(StorageAccessPolicy.Scope sc,StorageRegistry.Record row,Permission op,long tick){var c=reader.check(sc,row.id(),op,new ItemStack(Items.OAK_PLANKS));return c.eligible()?new StorageResolver.Observation(sc,c.binding(),tick,true,true,StorageResolver.Eligibility.ELIGIBLE):null;}
  },new StorageResolver.SelectionPort(){public StorageResolver.Selection consume(StorageAccessPolicy.Scope sc,UUID id,long tick){return null;}public boolean current(StorageAccessPolicy.Scope sc,StorageResolver.Selection selected,Binding b,long tick){return false;}},new RecipientResolver(new RecipientResolver.Port(){public RecipientResolver.View view(StorageAccessPolicy.Scope sc,long tick){return null;}public RecipientResolver.Citizen lookup(StorageAccessPolicy.Scope sc,UUID id,long tick){return null;}},level::getGameTime),level::getGameTime);
  var json=new TreeMap<String,Object>(Map.of("schema","cc.cd/1.0.0","kind","StorageSelector","body",new TreeMap<>(Map.of("kind","NAMED","label",registry.snapshot().records().get(target.storage()).label(),"container_type","CHEST"))));var selector=dev.aivillages.core.kernel.storage.contract.StorageCodec.decode(DComeScene.JSON.toJson(json)+"\n");return resolver.begin(scope,selector,operation);
 }
 MobilityObservation tick(){long start=System.nanoTime();var state=route.step();frame("MOVE",Map.of("observation",state,"step_ns",System.nanoTime()-start));return state;}
 TransferObservation deposit(){long ns=System.nanoTime();last=transfer.deposit(batch);transferNs=System.nanoTime()-ns;session.observe(last);frame("DEPOSIT",last);return last;}
 static void fill(Container c,Item item,int amount){c.clearContent();int max=new ItemStack(item).getMaxStackSize();for(int i=0;i<c.getContainerSize() && amount>0;i++){int n=Math.min(max,amount);c.setItem(i,new ItemStack(item,n));amount-=n;}if(amount!=0)throw new IllegalArgumentException("fixture capacity");c.setChanged();}
 void grants(Set<Permission> ops,Runnable after){var snapshot=registry.snapshot();when(level,registry.updateAcl(new Caller(world,DNativeScene.PRINCIPAL),snapshot.revision(),destination.storage(),snapshot.records().get(destination.storage()).revision(),List.of(new Grant(new Owner(OwnerKind.PUBLIC,null),ops))),a->{ack(a);identities.updateMetadata(registry.snapshot());frame("GRANTS_CHANGED",null);after.run();});}
 void rename(Runnable after){var snapshot=registry.snapshot();when(level,registry.rename(new Caller(world,DNativeScene.PRINCIPAL),snapshot.revision(),destination.storage(),snapshot.records().get(destination.storage()).revision(),"renamed-destination"),a->{ack(a);identities.updateMetadata(registry.snapshot());frame("DESTINATION_RENAMED",null);after.run();});}
 void revoke(Runnable after){var snapshot=registry.snapshot();when(level,registry.updateAcl(new Caller(world,DNativeScene.PRINCIPAL),snapshot.revision(),destination.storage(),snapshot.records().get(destination.storage()).revision(),List.of()),a->{ack(a);identities.updateMetadata(registry.snapshot());frame("REVOKED",null);after.run();});}
 void frame(String event,Object detail){var out=new TreeMap<String,Object>();out.put("case",caseId);out.put("campaign",campaign);out.put("event",event);out.put("tick",level.getGameTime());out.put("world",world);out.put("principal",scope.principal());out.put("actor",arena.actor.getUUID());out.put("request",session==null?null:session.goal().request());out.put("goal",session==null?null:session.goal());out.put("route",route==null?null:route.goal());out.put("path_nodes",route==null?0:route.pathNodes());out.put("path_length",route==null?0:route.pathLength());out.put("checked_chunks",route==null?0:route.checkedChunks());out.put("source_binding",source==null?null:source.wire().body());out.put("destination_binding",destination==null?null:destination.wire().body());out.put("source_native",nativeBlock(sourcePos));out.put("destination_native",nativeBlock(destPos));out.put("source",stacks(source()));out.put("carrier",stacks(arena.actor.getInventory()));out.put("destination",stacks(destination()));out.put("native_feet",List.of(arena.actor.getX(),arena.actor.getY(),arena.actor.getZ()));out.put("source_pos",List.of(sourcePos.getX(),sourcePos.getY(),sourcePos.getZ()));out.put("destination_pos",List.of(destPos.getX(),destPos.getY(),destPos.getZ()));out.put("detail",detail);out.put("transfer_ns",transferNs);out.put("phase",session==null?null:session.phase());out.put("delivered",session==null?0:session.delivered());out.put("in_flight",session==null?0:session.inFlight());out.put("custody_revision",custodyRevision);out.put("integration_root",null);out.put("save_proof",null);out.put("seed",level.getSeed());out.put("forced_chunks",level.getChunkSource().getForceLoadedChunks().size());out.put("heap_used_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());DComeScene.writeLine(evidence.resolve("courier.jsonl"),out);System.out.println("CC_D08_FRAME "+DComeScene.JSON.toJson(out));}
 Map<String,Object> nativeBlock(BlockPos p){var row=new TreeMap<String,Object>();row.put("block",net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(level.getBlockState(p).getBlock()).toString());var entity=level.getBlockEntity(p);row.put("marker",entity instanceof StorageMarkerAccess a?a.cognitivecraft$marker():null);row.put("saved_nbt",entity==null?null:entity.saveWithFullMetadata(level.registryAccess()).toString());return row;}
 List<Map<String,Object>> stacks(Container c){var rows=new ArrayList<Map<String,Object>>();for(int i=0;i<c.getContainerSize();i++){var x=c.getItem(i);var m=new TreeMap<String,Object>();m.put("slot",i);m.put("count",x.getCount());m.put("item",x.isEmpty()?null:reader.describeItem(x));m.put("native_item_id",x.isEmpty()?null:net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(x.getItem()).toString());m.put("native_codec",x.isEmpty()?null:ItemStack.CODEC.encodeStart(level.registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE),x.copyWithCount(1)).getOrThrow().toString());m.put("native_default",x.getComponentsPatch().isEmpty());m.put("native_max_stack",x.getMaxStackSize());rows.add(m);}return rows;}
}
